1	package consensus
2	
3	import (
4		"crypto/sha256"
5		"encoding/binary"
6		"encoding/hex"
7		"encoding/json"
8		"errors"
9		"fmt"
10		"os"
11		"path/filepath"
12		"sort"
13		"sync"
14	)
15	
16	// Config 是节点初始化时固定的配置。
17	type Config struct {
18		// Seed 决定每轮提议者的种子，任意非空字节。
19		Seed []byte
20		// Validators 固定、非空、无重复的验证者公钥名单（Ed25519 32 字节公钥）。
21		Validators [][]byte
22		// MaxTxsPerBlock 单块交易上限，必须为正整数。
23		MaxTxsPerBlock uint64
24		// PoolCapacity 交易池容量上限：非负整数，0（或省略）表示不限制。
25		// 与单块交易上限相互独立；只统计排队与等待投票的交易。
26		PoolCapacity uint64
27	}
28	
29	// entryStatus 与对外的 TxStatus 取值一致，额外区分内部存储。
30	type entryStatus string
31	
32	const (
33		stQueued    entryStatus = "queued"
34		stProposed  entryStatus = "proposed"
35		stConfirmed entryStatus = "confirmed"
36		stReplaced  entryStatus = "replaced"
37		stExpired   entryStatus = "expired"
38		stDropped   entryStatus = "dropped"
39	)
40	
41	type poolEntry struct {
42		Tx         *Transaction `json:"tx"`
43		Status     entryStatus  `json:"status"`
44		ReplacedBy string       `json:"replaced_by,omitempty"`
45		// DropReason/DropRound 仅在 Status 为 dropped 时有意义：被挤出的原因与发生轮次。
46		DropReason string `json:"drop_reason,omitempty"`
47		DropRound  uint64 `json:"drop_round,omitempty"`
48	}
49	
50	type confirmedRef struct {
51		Height uint64 `json:"height"`
52		Block  string `json:"block_id"`
53	}
54	
55	type proposalState struct {
56		Round   uint64   `json:"round"`
57		TxIDs   []string `json:"tx_ids"`
58		BlockID string   `json:"block_id"`
59		Votes   []string `json:"votes"` // 已投票验证者公钥的十六进制，按字典序保存
60	}
61	
62	// candidateState 是一轮中的一个候选块。同一轮多个候选共享相同的轮次、
63	// 下一高度与前块标识，仅交易顺序可以不同。
64	type candidateState struct {
65		TxIDs   []string `json:"tx_ids"`
66		BlockID string   `json:"block_id"`
67		Votes   []string `json:"votes"` // 已投票验证者公钥的十六进制，按字典序保存
68		// Local 标记该候选是否为本节点 Propose 产生的本地提议。
69		Local bool `json:"local"`
70		// Decided 表示该候选已决出：胜出确认或在轮次结束时落选。
71		Decided bool `json:"decided"`
72		// Winner 仅在 Decided 时有意义：true 为胜出，false 为落选。
73		Winner bool `json:"winner,omitempty"`
74	}
75	
76	// roundState 记录一个轮次的全部候选与结果。轮次决出后仍保留用于历史查询。
77	type roundState struct {
78		Round        uint64                     `json:"round"`
79		Height       uint64                     `json:"height"`     // 该轮候选使用的下一高度
80		PreviousID   string                     `json:"prev_id"`    // 该轮候选接在其后的最新确认块
81		Candidates   map[string]*candidateState `json:"candidates"` // 区块标识 -> 候选
82		LocalBlockID string                     `json:"local_block_id"`
83		// Ended 本轮已决出：候选确认或被 EndRound 主动结束。
84		Ended bool `json:"ended"`
85		// EndedByConfirm 决出方式：true 为投票确认，false 为主动结束（全部落选）。
86		EndedByConfirm bool `json:"ended_by_confirm,omitempty"`
87		// DetailMissing 表示该轮候选详情由旧版本状态迁移而来、并未保存，
88		// 查询时明确显示无记录；确认块本身不受影响。
89		DetailMissing bool `json:"detail_missing,omitempty"`
90	}
91	
92	// state 是持久化到磁盘的完整节点状态。
93	type state struct {
94		Version    int      `json:"version"`
95		Seed       []byte   `json:"seed"`
96		Validators [][]byte `json:"validators"`
97		MaxTxs     uint64   `json:"max_txs_per_block"`
98		// Capacity 交易池容量上限，0 表示不限制。版本 1、2 的状态未保存该字段，
99		// 打开时保持零值，即按不限制处理。
100		Capacity  uint64                       `json:"pool_capacity"`
101		Round     uint64                       `json:"round"`
102		LastBlock string                       `json:"last_block_id"`
103		Accounts  map[string]uint64            `json:"accounts"` // 发送者十六进制公钥 -> 已确认序号
104		Pool      map[string]map[uint64]string `json:"pool"`     // 发送者 -> 序号 -> 交易标识（含已提议交易）
105		Entries   map[string]*poolEntry        `json:"entries"`
106		Confirmed map[string]confirmedRef      `json:"confirmed"`
107		Blocks    []Block                      `json:"blocks"`
108		// Rounds 按轮次保存候选与结果，含已决出的历史轮次。
109		Rounds map[uint64]*roundState `json:"rounds,omitempty"`
110		// Proposal 仅用于读取版本 1 的旧状态文件；版本 2 起一律由 Rounds 表达。
111		Proposal *proposalState `json:"proposal,omitempty"`
112	}
113	
114	const stateVersion = 3
115	const stateFileName = "state.json"
116	
117	// Node 是一个本地共识节点。一个进程内可串行调用其方法。
118	type Node struct {
119		dir string
120		mu  sync.Mutex
121		st  *state
122		// injectSaveErr 仅供同包测试使用：非 nil 时 save 直接失败，模拟写入错误。
123		injectSaveErr error
124	}
125	
126	func validateConfig(cfg Config) error {
127		if len(cfg.Seed) == 0 {
128			return errors.New("seed must be non-empty")
129		}
130		if len(cfg.Validators) == 0 {
131			return errors.New("validators must be non-empty")
132		}
133		if cfg.MaxTxsPerBlock == 0 {
134			return errors.New("max txs per block must be a positive integer")
135		}
136		seen := make(map[string]struct{}, len(cfg.Validators))
137		for i, v := range cfg.Validators {
138			if len(v) == 0 {
139				return fmt.Errorf("validator %d is empty", i)
140			}
141			key := fmt.Sprintf("%x", v)
142			if _, ok := seen[key]; ok {
143				return fmt.Errorf("duplicate validator %s", key)
144			}
145			seen[key] = struct{}{}
146		}
147		return nil
148	}
149	
150	// New 在 dir 中初始化一个新节点。目录不存在会创建；若已有状态文件则报错，
151	// 以免覆盖既有链历史，请改用 Open。
152	func New(dir string, cfg Config) (*Node, error) {
153		if err := validateConfig(cfg); err != nil {
154			return nil, err
155		}
156		if err := os.MkdirAll(dir, 0o755); err != nil {
157			return nil, err
158		}
159		path := filepath.Join(dir, stateFileName)
160		if _, err := os.Stat(path); err == nil {
161			return nil, fmt.Errorf("state file already exists at %s; use Open to resume", path)
162		}
163		validators := make([][]byte, len(cfg.Validators))
164		for i, v := range cfg.Validators {
165			validators[i] = append([]byte(nil), v...)
166		}
167		st := &state{
168			Version:    stateVersion,
169			Seed:       append([]byte(nil), cfg.Seed...),
170			Validators: validators,
171			MaxTxs:     cfg.MaxTxsPerBlock,
172			Capacity:   cfg.PoolCapacity,
173			Round:      1, // 轮次从 1 开始
174			Accounts:   map[string]uint64{},
175			Pool:       map[string]map[uint64]string{},
176			Entries:    map[string]*poolEntry{},
177			Confirmed:  map[string]confirmedRef{},
178			Blocks:     []Block{},
179			Rounds:     map[uint64]*roundState{},
180		}
181		n := &Node{dir: dir, st: st}
182		if err := n.save(st); err != nil {
183			return nil, err
184		}
185		return n, nil
186	}
187	
188	// Open 从 dir 恢复此前由 New 创建的节点，恢复轮次、交易池、未决候选、
189	// 每人已投的选择、票数与确认历史。版本 1 的旧状态目录仍可打开。
190	func Open(dir string) (*Node, error) {
191		path := filepath.Join(dir, stateFileName)
192		raw, err := os.ReadFile(path)
193		if err != nil {
194			return nil, err
195		}
196		st := &state{}
197		if err := json.Unmarshal(raw, st); err != nil {
198			return nil, fmt.Errorf("corrupt state file %s: %w", path, err)
199		}
200		if st.Version < 1 || st.Version > stateVersion {
201			return nil, fmt.Errorf("unsupported state version %d", st.Version)
202		}
203		if st.Round == 0 {
204			st.Round = 1
205		}
206		if st.Rounds == nil {
207			st.Rounds = map[uint64]*roundState{}
208		}
209		if st.Version == 1 {
210			migrateV1(st)
211		}
212		// 版本 1、2 的状态未保存容量：Capacity 保持零值，即不限制；确认历史原样保留。
213		st.Version = stateVersion
214		return &Node{dir: dir, st: st}, nil
215	}
216	
217	// migrateV1 把版本 1 状态迁移到当前版本：
218	// 未决提议与其票数恢复为当前轮次的本地候选；旧版本未保存候选详情，
219	// 历史轮次一律标记为无记录（其中确认轮仍可通过确认块查询），已有确认块不变。
220	func migrateV1(st *state) {
221		st.Version = stateVersion
222		// 1..Round-1 中每个已跳过的轮次都没有保存候选详情；
223		// 无确认块即说明该轮经 EndRound 结束、未确认。
224		for r := uint64(1); r < st.Round; r++ {
225			if _, ok := st.Rounds[r]; ok {
226				continue
227			}
228			st.Rounds[r] = &roundState{
229				Round:         r,
230				Candidates:    map[string]*candidateState{},
231				Ended:         true,
232				DetailMissing: true,
233			}
234		}
235		for _, b := range st.Blocks {
236			st.Rounds[b.Round] = &roundState{
237				Round:          b.Round,
238				Height:         b.Height,
239				PreviousID:     b.PreviousID,
240				Candidates:     map[string]*candidateState{},
241				LocalBlockID:   b.ID,
242				Ended:          true,
243				EndedByConfirm: true,
244				DetailMissing:  true,
245			}
246		}
247		if st.Proposal != nil {
248			p := st.Proposal
249			rs := &roundState{
250				Round:      p.Round,
251				Height:     uint64(len(st.Blocks)) + 1,
252				PreviousID: st.LastBlock,
253				Candidates: map[string]*candidateState{
254					p.BlockID: &candidateState{
255						TxIDs:   append([]string{}, p.TxIDs...),
256						BlockID: p.BlockID,
257						Votes:   append([]string{}, p.Votes...),
258						Local:   true,
259					},
260				},
261				LocalBlockID: p.BlockID,
262			}
263			// 被未决提议引用的交易在版本 1 中已标记为 proposed，语义不变，原样保留。
264			st.Rounds[p.Round] = rs
265		}
266		st.Proposal = nil
267	}
268	
269	// ConfigSnapshot 返回节点的固定配置副本。
270	type ConfigSnapshot struct {
271		Seed           []byte
272		Validators     [][]byte
273		MaxTxsPerBlock uint64
274		// PoolCapacity 交易池容量上限，0 表示不限制。
275		PoolCapacity uint64
276	}
277	
278	// Config 返回初始化时的配置副本。
279	func (n *Node) Config() ConfigSnapshot {
280		n.mu.Lock()
281		defer n.mu.Unlock()
282		vals := make([][]byte, len(n.st.Validators))
283		for i, v := range n.st.Validators {
284			vals[i] = append([]byte(nil), v...)
285		}
286		return ConfigSnapshot{
287			Seed:           append([]byte(nil), n.st.Seed...),
288			Validators:     vals,
289			MaxTxsPerBlock: n.st.MaxTxs,
290			PoolCapacity:   n.st.Capacity,
291		}
292	}
