121	// TestDecisiveVoteSaveFailureAtomic 覆盖决定性投票保存失败的完整回归序列：
122	// 失败整体回滚 -> 内存/磁盘/重开三处一致 -> 恢复后再次投票作为新票确认。
123	func TestDecisiveVoteSaveFailureAtomic(t *testing.T) {
124		keys := genKeys(t, 4)
125		n, dir := newTestNode(t, keys, 10)
126	
127		// 两笔不同账户的交易，到期轮次足够大：进入第 2 轮也不会失效。
128		a1 := NewTransaction(keys[0].priv, 1, []byte("a1"), 1, 100)
129		b1 := NewTransaction(keys[1].priv, 1, []byte("b1"), 5, 100)
130		if _, err := n.Submit(a1); err != nil {
131			t.Fatal(err)
132		}
133		if _, err := n.Submit(b1); err != nil {
134			t.Fatal(err)
135		}
136		// 费用 b1(5) 高于 a1(1)：本地提议顺序固定为 b1、a1，两笔都在提议中。
137		local, err := n.Propose()
138		if err != nil {
139			t.Fatal(err)
140		}
141		if fmt.Sprint(local.TxIDs) != fmt.Sprint([]string{b1.ID(), a1.ID()}) {
142			t.Fatalf("setup: local proposal = %v, want [b1 a1]", local.TxIDs)
143		}
144		// 竞争候选只含 a1，标识与交易顺序都不同于本地提议。
145		alt, err := n.RegisterCandidate(1, []string{a1.ID()})
146		if err != nil {
147			t.Fatal(err)
148		}
149		if alt.BlockID == local.BlockID {
150			t.Fatal("setup: competitor block id must differ from local proposal")
151		}
152	
153		// 两名验证者投给竞争候选：两票未达严格超过 2/3 的门槛，不能确认。
154		firstVoters := [][]byte{keys[0].pub, keys[1].pub}
155		for i, v := range firstVoters {
156			res, err := n.Vote(v, 1, alt.BlockID)
157			if err != nil || !res.Counted || res.Confirmed {
158				t.Fatalf("competitor vote %d: %+v %v", i+1, res, err)
159			}
160		}
161		decisive := keys[2].pub
162		stillUnvoted := [][]byte{keys[2].pub, keys[3].pub}
163		assertRoundOnePending(t, n, local, alt.BlockID, firstVoters, stillUnvoted, a1, b1, keys)
164	
165		// 记录决定性投票前的磁盘文件：后续失败的保存不得改动它。
166		statePath := filepath.Join(dir, stateFileName)
167		before, err := os.ReadFile(statePath)
168		if err != nil {
169			t.Fatal(err)
170		}
171	
172		// 第三名验证者本应使竞争候选胜出，但此刻保存节点状态失败。
173		n.injectSaveErr = errors.New("disk full (simulated)")
174		res, err := n.Vote(decisive, 1, alt.BlockID)
175		n.injectSaveErr = nil
176		if err == nil {
177			t.Fatal("decisive vote must return an error when saving node state fails")
178		}
179		if reason(err) != "" {
180			t.Fatalf("save failure must surface as an infrastructure error, not a vote rejection %q: %v", reason(err), err)
181		}
182		if res != nil {
183			t.Fatalf("vote result must be nil on save failure, got %+v", res)
184		}
185	
186		// 内存：轮次、高度、最新块、候选票数/结果、未投票者、提议、交易与账户全部照旧。
187		assertRoundOnePending(t, n, local, alt.BlockID, firstVoters, stillUnvoted, a1, b1, keys)
188	
189		// 磁盘：状态文件逐字节保持投票前内容，且不残留临时文件。
190		after, err := os.ReadFile(statePath)
191		if err != nil {
192			t.Fatal(err)
193		}
194		if string(after) != string(before) {
195			t.Fatal("state file changed despite the failed save")
196		}
197		entries, err := os.ReadDir(dir)
198		if err != nil {
199			t.Fatal(err)
200		}
201		var names []string
202		for _, e := range entries {
203			names = append(names, e.Name())
204		}
205		if fmt.Sprint(names) != "[state.json]" {
206			t.Fatalf("failed save must not leave temp files, dir contains %v", names)
207		}
208	
209		// 重开节点：看到同样的操作前状态——不多出确认块，也没有只落在内存或
210		// 只落在保存记录里的第三票。
211		reopened, err := Open(dir)
212		if err != nil {
213			t.Fatal(err)
214		}
215		assertRoundOnePending(t, reopened, local, alt.BlockID, firstVoters, stillUnvoted, a1, b1, keys)
216	
217		// 保存恢复正常后，同一名验证者再次投给同一竞争候选：
218		// 必须作为新票（Counted）被接收并立即确认，而非被当成重复投票去重。
219		res, err = reopened.Vote(decisive, 1, alt.BlockID)
220		if err != nil {
221			t.Fatalf("decisive vote after recovery: %v", err)
222		}
223		if !res.Counted {
224			t.Fatal("the repeated vote must count as a new vote, not dedup as an earlier failed one")
225		}
226		if !res.Confirmed || res.Block == nil {
227			t.Fatalf("competitor must confirm immediately on the third durable vote: %+v", res)
228		}
229		if res.Block.ID != alt.BlockID || fmt.Sprint(res.Block.TxIDs) != fmt.Sprint([]string{a1.ID()}) {
230			t.Fatalf("returned block must match competitor id and tx order: %+v", res.Block)
231		}
232		if res.Block.Height != 1 || res.Block.Round != 1 || res.Block.PreviousID != "" {
233			t.Fatalf("returned block header wrong: %+v", res.Block)
234		}
235	
236		// 节点进入下一轮，确认高度推进，最新块即竞争候选块。
237		if reopened.CurrentRound() != 2 || reopened.Height() != 1 {
238			t.Fatalf("round=%d height=%d after confirmation, want 2/1", reopened.CurrentRound(), reopened.Height())
239		}
240		blk, err := reopened.BlockAt(1)
241		if err != nil {
242			t.Fatal(err)
243		}
244		if blk.ID != alt.BlockID || blk.Round != 1 || blk.Height != 1 || blk.PreviousID != "" ||
245			fmt.Sprint(blk.TxIDs) != fmt.Sprint([]string{a1.ID()}) {
